27	/// A C++ convenience wrapper for orc_rt_WrapperFunctionBuffer. Auto-disposes
28	/// the contained result on destruction.
29	class WrapperFunctionBuffer {
30	public:
31	  /// Create a default WrapperFunctionBuffer.
32	  WrapperFunctionBuffer() { orc_rt_WrapperFunctionBufferInit(&B); }
33	
34	  /// Create a WrapperFunctionBuffer from a WrapperFunctionBuffer. This
35	  /// instance takes ownership of the result object and will automatically
36	  /// call dispose on the result upon destruction.
37	  explicit WrapperFunctionBuffer(orc_rt_WrapperFunctionBuffer B) : B(B) {}
38	
39	  WrapperFunctionBuffer(const WrapperFunctionBuffer &) = delete;
40	  WrapperFunctionBuffer &operator=(const WrapperFunctionBuffer &) = delete;
41	
42	  WrapperFunctionBuffer(WrapperFunctionBuffer &&Other) {
43	    orc_rt_WrapperFunctionBufferInit(&B);
44	    std::swap(B, Other.B);
45	  }
46	
47	  WrapperFunctionBuffer &operator=(WrapperFunctionBuffer &&Other) {
48	    orc_rt_WrapperFunctionBufferDispose(&B);
49	    orc_rt_WrapperFunctionBufferInit(&B);
50	    std::swap(B, Other.B);
51	    return *this;
52	  }
53	
54	  ~WrapperFunctionBuffer() { orc_rt_WrapperFunctionBufferDispose(&B); }
55	
56	  /// Relinquish ownership of and return the
57	  /// orc_rt_WrapperFunctionBuffer.
58	  orc_rt_WrapperFunctionBuffer release() {
59	    orc_rt_WrapperFunctionBuffer Tmp;
60	    orc_rt_WrapperFunctionBufferInit(&Tmp);
61	    std::swap(B, Tmp);
62	    return Tmp;
63	  }
64	
65	  /// Get a pointer to the data contained in this instance.
66	  char *data() { return orc_rt_WrapperFunctionBufferData(&B); }
67	
68	  /// Get a pointer to the data contained is this instance.
69	  const char *data() const { return orc_rt_WrapperFunctionBufferConstData(&B); }
70	
71	  /// Returns the size of the data contained in this instance.
72	  size_t size() const { return orc_rt_WrapperFunctionBufferSize(&B); }
73	
74	  /// Returns true if this value is equivalent to a default-constructed
75	  /// WrapperFunctionBuffer.
76	  bool empty() const { return orc_rt_WrapperFunctionBufferEmpty(&B); }
77	
78	  /// Create a WrapperFunctionBuffer with the given size and return a pointer
79	  /// to the underlying memory.
80	  static WrapperFunctionBuffer allocate(size_t Size) {
81	    return WrapperFunctionBuffer(orc_rt_WrapperFunctionBufferAllocate(Size));
82	  }
83	
84	  /// Copy from the given char range.
85	  static WrapperFunctionBuffer copyFrom(const char *Source, size_t Size) {
86	    return WrapperFunctionBuffer(
87	        orc_rt_CreateWrapperFunctionBufferFromRange(Source, Size));
88	  }
89	
90	  /// Copy from the given null-terminated string (includes the null-terminator).
91	  static WrapperFunctionBuffer copyFrom(const char *Source) {
92	    return WrapperFunctionBuffer(
93	        orc_rt_CreateWrapperFunctionBufferFromString(Source));
94	  }
95	
96	  /// Create an out-of-band error by copying the given string.
97	  static WrapperFunctionBuffer createOutOfBandError(const char *Msg) {
98	    return WrapperFunctionBuffer(
99	        orc_rt_CreateWrapperFunctionBufferFromOutOfBandError(Msg));
100	  }
101	
102	  /// If this value is an out-of-band error then this returns the error message,
103	  /// otherwise returns nullptr.
104	  const char *getOutOfBandError() const {
105	    return orc_rt_WrapperFunctionBufferGetOutOfBandError(&B);
106	  }
107	
108	private:
109	  orc_rt_WrapperFunctionBuffer B;
110	};
