11	//===----------------------------------------------------------------------===//
12	
13	#ifndef ORC_RT_TASKGROUP_H
14	#define ORC_RT_TASKGROUP_H
15	
16	#include "move_only_function.h"
17	
18	#include <cassert>
19	#include <memory>
20	#include <mutex>
21	#include <vector>
22	
23	namespace orc_rt {
24	
25	/// TaskGroup tracks execution of a set of tasks, providing notification when
26	/// all tasks have completed.
27	class TaskGroup {
28	public:
29	  class Token;
30	
31	  /// A strong reference to a TaskGroup, used only to construct Tokens from it
32	  /// (see Token). It exposes no operations of its own: acquisition lives on the
33	  /// Token constructor so that Token remains the single point that knows the
34	  /// acquire/release protocol. A TokenSource keeps the referenced TaskGroup
35	  /// alive, but does not hold a Token and so does not prevent the group from
36	  /// closing or completing.
37	  class TokenSource {
38	    friend class Token;
39	
40	  public:
41	    TokenSource(std::shared_ptr<TaskGroup> TG) : TG(std::move(TG)) {}
42	
43	  private:
44	    std::shared_ptr<TaskGroup> TG;
45	  };
46	
47	  /// Token represents the right to proceed with a task as part of a
48	  /// TaskGroup.
49	  ///
50	  /// Construction (from a TaskGroup or by copy) may fail if the group is
51	  /// closed. Always check validity with operator bool() before proceeding:
52	  ///
53	  ///   Token T(TG);
54	  ///   if (!T) return;  // Group was closed
55	  ///
56	  /// WARNING: Avoid storing Tokens in long-lived data structures. The TaskGroup
57	  /// cannot complete while any Token exists, so stashing copies may
58	  /// unintentionally defer completion.
59	  class Token {
60	  public:
61	    /// Construct an empty Token not associated with any TaskGroup.
62	    Token() = default;
63	
64	    /// Attempt to create a copy of the given Token.
65	    /// Note that this may fail if the TaskGroup has been closed. Clients must
66	    /// check whether the Token is valid (using operator bool()) before
67	    /// continuing with their task.
68	    Token(const Token &Other) {
69	      if (Other.G && Other.G->acquireToken())
70	        G = Other.G;
71	    }
72	
73	    /// Attempt to overwrite this Token.
74	    /// Note that this will:
75	    ///   1. Trigger task group completion if this Token represented the last
76	    ///      running task in the TaskGroup and Other is an empty Token.
77	    ///   2. Fail if the TaskGroup referenced by Other has been closed. Clients
78	    ///      must check whether the Token is valid (using operator bool())
79	    ///      before continuing with their task.
80	    Token &operator=(const Token &Other) {
81	      if (&Other == this)
82	        return *this;
83	
84	      if (G)
85	        G->releaseToken();
86	      if (Other.G && Other.G->acquireToken())
87	        G = Other.G;
88	      else
89	        G = nullptr;
90	
91	      return *this;
92	    }
93	
94	    /// Move-construct from Other.
95	    Token(Token &&Other) { std::swap(G, Other.G); }
96	
97	    /// Move-assign from Other.
98	    ///
99	    /// Note that this will trigger task group completion if this Token
100	    /// represented the last running task in the TaskGroup and Other is an
101	    /// empty Token.
102	    Token &operator=(Token &&Other) {
103	      if (this == &Other)
104	        return *this;
105	      if (G) {
106	        G->releaseToken();
107	        G = nullptr;
108	      }
109	      std::swap(G, Other.G);
110	      return *this;
111	    }
112	
113	    /// Construct a Token from the given TaskGroup.
114	    /// Note that this may fail if the TaskGroup has been closed. Clients must
115	    /// check whether the resulting Token is valid (using operator bool())
116	    /// before continuing with their task.
117	    Token(std::shared_ptr<TaskGroup> G) {
118	      if (G && G->acquireToken())
119	        this->G = std::move(G);
120	    }
121	
122	    /// Construct a Token from the given TokenSource.
123	    /// Note that this may fail if the TaskGroup has been closed. Clients must
124	    /// check whether the resulting Token is valid (using operator bool())
125	    /// before continuing with their task.
126	    Token(const TokenSource &S) : Token(S.TG) {}
127	
128	    /// Destroys this Token, potentially triggering task group completion if
129	    /// this Token represented the last running task in the TaskGroup.
130	    ~Token() {
131	      if (G)
132	        G->releaseToken();
133	    }
134	
135	    /// Returns true if this Token is valid and attached to a task group.
136	    explicit operator bool() const noexcept { return !!G; }
137	
138	  private:
139	    std::shared_ptr<TaskGroup> G;
140	  };
141	
142	  using OnCompleteFn = move_only_function<void()>;
143	
144	  TaskGroup(const TaskGroup &) = delete;
145	  TaskGroup &operator=(const TaskGroup &) = delete;
146	  TaskGroup(TaskGroup &&) = delete;
147	  TaskGroup &operator=(TaskGroup &&) = delete;
148	
149	  static std::shared_ptr<TaskGroup> Create() noexcept {
150	    return std::shared_ptr<TaskGroup>(new TaskGroup());
151	  }
152	
153	  /// Increment the number of tasks in this group if it is still open.
154	  /// Returns true on success, false on failure.
155	  bool acquireToken() noexcept {
156	    std::scoped_lock<std::mutex> Lock(M);
157	    if (Closed)
158	      return false;
159	    ++NumTasks;
160	    return true;
161	  }
